/**
 * BOT_TOKEN expiry reminder — runs on a schedule inside GitHub Actions.
 *
 * When the GitHub PAT that powers the anki-browser-api Worker (secret
 * BOT_TOKEN) is close to expiring (or already has), this opens or updates a
 * labelled issue in the repo so the owner is notified on GitHub itself.
 *
 * Nothing here depends on an AI agent or any external service — the reminder
 * is a property of the repository, so it keeps working no matter which tool
 * (if any) the owner uses to develop the site.
 *
 * Expiry date source: the repository variable `BOT_TOKEN_EXPIRY` (YYYY-MM-DD),
 * falling back to the default below. After rotating the token, update the
 * variable in Settings → Secrets and variables → Actions → Variables.
 */
const EXPIRY_DEFAULT = '2027-07-14';
const REMIND_WITHIN_DAYS = 60;
const LABEL = 'token-expiry';

const owner = process.env.OWNER || 'geograhic';
const repo = process.env.REPO || 'anki-browser';
const token = process.env.GH_TOKEN;
const expiryStr = (process.env.EXPIRY || EXPIRY_DEFAULT).trim();

if (!token) {
  console.error('GH_TOKEN is required.');
  process.exit(1);
}

const now = new Date();
const exp = new Date(expiryStr + 'T00:00:00Z');
const daysLeft = Math.ceil((exp - now) / 86400000);
console.log(`BOT_TOKEN expires ${expiryStr}; ${daysLeft} days from now.`);

if (daysLeft > REMIND_WITHIN_DAYS) {
  console.log(`More than ${REMIND_WITHIN_DAYS} days left — no reminder needed.`);
  process.exit(0);
}

const api = 'https://api.github.com';
const headers = {
  Authorization: `Bearer ${token}`,
  'User-Agent': 'anki-browser-token-reminder',
  Accept: 'application/vnd.github+json',
  'Content-Type': 'application/json',
};

async function gh(method, path, body) {
  const res = await fetch(api + path, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  let data = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = null;
  }
  if (!res.ok) {
    console.error(`GH ${method} ${path} -> ${res.status}: ${text.slice(0, 300)}`);
    process.exit(1);
  }
  return data;
}

const status =
  daysLeft <= 0
    ? '**EXPIRED** — submissions and moderation are failing with 401s right now.'
    : `expires in **${daysLeft} day${daysLeft === 1 ? '' : 's'}** (${expiryStr}).`;
const title = `⚠️ GitHub PAT (BOT_TOKEN) ${daysLeft <= 0 ? 'EXPIRED ' + expiryStr : 'expires ' + expiryStr + ' (' + daysLeft + 'd)'}`;
const body = [
  `## 🔑 GitHub PAT (BOT_TOKEN) ${daysLeft <= 0 ? 'has expired' : 'is close to expiring'}`,
  '',
  `The personal access token used by the \`anki-browser-api\` Worker (secret \`BOT_TOKEN\`) ${status}`,
  '',
  '### What breaks when it expires',
  '- Visitor **deck submissions** (the Worker opens the issue in `anki-browser-submissions`)',
  '- **Moderation**: approve → the commit to `public/decks/index.json`, reject, unpublish',
  '- Local GitHub API tooling that reads this token from the KeePass vault',
  '',
  '### How to fix (rotate)',
  '1. Generate a new classic PAT at https://github.com/settings/tokens (or set **No expiration**).',
  '2. Update the `GitHub PAT 20260714` entry in your KeePass vault (`AI-dev-key-v20260714.kdbx`).',
  '3. Redeploy the Worker so its `BOT_TOKEN` secret uses the new value:',
  '   ```bash',
  '   npm run deploy:api   # requires CF_API_TOKEN / BOT_TOKEN / CF_ACCOUNT_ID / CF_ZONE_ID / SESSION_SECRET / ADMIN_LOGINS env',
  '   ```',
  '4. Update the **`BOT_TOKEN_EXPIRY`** repository variable (Settings → Secrets and variables → Actions → Variables) to the new expiry date, then **close this issue**.',
  '',
  '> For a smaller blast radius, consider a **fine-grained PAT** limited to `Contents` (read/write) on `geograhic/anki-browser` and `Issues` (read/write) on `geograhic/anki-browser-submissions`.',
  '',
  `_Generated by the repository's own scheduled reminder (${new Date().toISOString()})._`,
].join('\n');

// Find an existing open reminder so we update instead of duplicating.
const openIssues = await gh(`/repos/${owner}/${repo}/issues?state=open&labels=${encodeURIComponent(LABEL)}&per_page=30`);
const mine = (openIssues || []).find((i) => !i.pull_request);
if (mine) {
  await gh('PATCH', `/repos/${owner}/${repo}/issues/${mine.number}`, { title, body });
  console.log(`Updated reminder issue #${mine.number}.`);
} else {
  const created = await gh('POST', `/repos/${owner}/${repo}/issues`, {
    title,
    body,
    labels: [LABEL],
  });
  console.log(`Created reminder issue #${created.number}.`);
}
